fn concat(a: &[i32], b: &[i32]) -> Vec<i32> {
    // Create a new Vec with the capacity equal to the sum of the lengths of a and b
    let mut result = Vec::with_capacity(a.len() + b.len());
    
    // Extend the result with elements from the first slice
    result.extend_from_slice(a);
    
    // Extend the result with elements from the second slice
    result.extend_from_slice(b);
    
    // Return the concatenated result
    result
}